// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testRegression_property() public {
        c.SetMinSum(1);
        c.Initialized();
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        bool ok;
        try c.Collect(0) { ok = true; } catch { ok = false; }
        assertTrue(ok, "Bug should succeed (MinSum default 0) but reference reverts");
    }
}
